import fs from 'fs';
import path from 'node:path';

const root = process.cwd();
const appsPath = path.join(root, 'apps');

const sources = !fs.existsSync(appsPath) ? [] :
  fs.readdirSync(appsPath, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !d.name.startsWith('.'))
    .map((d) => d.name)
    .filter((app) => fs.existsSync(path.join(appsPath, app, 'modules')))
    .sort()
    .map((app) => `@source "../../apps/${app}/modules";`);

const content = [
  '/* autogenerated by bin/build/generate-auto.js — mirrors tailwinInit */',
  ...sources,
  '',
].join('\n');

const outDir = path.join(root, 'app', 'auto');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'tailwind-apps.css'), content);

console.log(`✓ app/auto/tailwind-apps.css (${sources.length} app source${sources.length === 1 ? '' : 's'})`);
